import{_ as a,o,c as t,a2 as r}from"./chunks/framework.C2TvIV46.js";const u=JSON.parse('{"title":"エクスポート","description":"","frontmatter":{},"headers":[],"relativePath":"ja/megacrow/export.md","filePath":"ja/megacrow/export.md"}'),l={name:"ja/megacrow/export.md"};function d(i,e,s,c,n,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="エクスポート" tabindex="-1">エクスポート <a class="header-anchor" href="#エクスポート" aria-label="Permalink to &quot;エクスポート&quot;">​</a></h1><p>ツールバーの <strong>Export</strong> で、現在の Megalo ゲームタイプをコンパイルし、選択したバイナリ形式で保存します。<strong>Export as</strong> メニューから形式を選びます。</p><p>どの形式も同じコンパイル済みバリアントから生成され、コンテナと想定用途だけが異なります。</p><h2 id="形式" tabindex="-1">形式 <a class="header-anchor" href="#形式" aria-label="Permalink to &quot;形式&quot;">​</a></h2><h3 id="mglo" tabindex="-1"><code>.mglo</code> <a class="header-anchor" href="#mglo" aria-label="Permalink to &quot;`.mglo`&quot;">​</a></h3><p><strong>向いている用途:</strong> ホットリロードおよび HREK / MCC の <code>maps/megalo</code> ワークフロー。</p><ul><li>最小のカスタムバリアントペイロード（生の Megalo ビットストリーム）</li><li>デバッグ／開発者向けリロード用に、ワークスペースの <strong>output folder</strong>（通常は <code>maps/megalo</code>）へ配置</li><li>バリアントを完全な BLF ドキュメントでは包まない</li></ul><p>スクリプトを反復し、ゲームの megalo maps ディレクトリから読み込むときに使います。</p><h3 id="gvar" tabindex="-1"><code>gvar</code> <a class="header-anchor" href="#gvar" aria-label="Permalink to &quot;`gvar`&quot;">​</a></h3><p><strong>向いている用途:</strong> Xbox 360 のマッチメイキング／デバッグ用ネットコマンド。</p><ul><li>Xbox 360 のマッチメイキング風ロード向けの BLF ラッパー</li><li>デバッグビルドでは <code>net_load_and_use_game_variant</code> で読み込み</li><li>BLF フレーミングのため <code>.mglo</code> より大きい</li></ul><p>File Share や MCC のセーブ形式ではなく、360 マッチメイキングの BLF パスが必要なときに <code>gvar</code> を選んでください。</p><h3 id="mpvr" tabindex="-1"><code>mpvr</code> <a class="header-anchor" href="#mpvr" aria-label="Permalink to &quot;`mpvr`&quot;">​</a></h3><p><strong>向いている用途:</strong> 通常のゲーム内セーブ、File Share、Xbox／PC のゲームタイプファイル。</p><ul><li>Reach カスタムバリアント向けの標準 BLF パッケージ</li><li>ゲーム内保存、File Share へのアップロード、Xbox／PC 間での共有に適する</li><li>一般的にやり取りされる「フル」なゲームタイプファイル</li></ul><p>生の <code>.mglo</code> ビットストリームではなく、通常の共有／読み込み可能なゲームタイプファイルが欲しいときは <code>mpvr</code> を選んでください。</p><h3 id="autosave-queue-asq" tabindex="-1">Autosave Queue（<code>asq</code>） <a class="header-anchor" href="#autosave-queue-asq" aria-label="Permalink to &quot;Autosave Queue（`asq`）&quot;">​</a></h3><p><strong>向いている用途:</strong> オートセーブキュー経由で <strong>Recent Games</strong> に表示する。</p><ul><li>単体のバリアント置き換えではなく、Autosave Queue ファイルを書き出す</li><li>ゲームがオートセーブキュー用に期待する場所に置けば、ゲームタイプが Recent Games に現れる</li><li>File Share や、毎回の <code>maps/megalo</code> 手動コピーを経ずにテストするのに便利</li></ul><h2 id="形式の選び方" tabindex="-1">形式の選び方 <a class="header-anchor" href="#形式の選び方" aria-label="Permalink to &quot;形式の選び方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>形式</th></tr></thead><tbody><tr><td><code>maps/megalo</code> での最速イテレーション</td><td><code>.mglo</code></td></tr><tr><td>360 デバッグの <code>net_load_and_use_game_variant</code></td><td><code>gvar</code></td></tr><tr><td>File Share／通常セーブ／クロスプラットフォーム</td><td><code>mpvr</code></td></tr><tr><td>オートセーブキュー経由の Recent Games</td><td>Autosave Queue</td></tr></tbody></table><p>エクスポート時のコンパイルには、現在の <a href="/MegaloEvolved/beta/docs/ja/megacrow/settings">設定</a>（作者名、コンパイラプロファイル、厳密コンパイラ）が使われます。</p>',22)])])}const m=a(l,[["render",d]]);export{u as __pageData,m as default};
